import Foundation
import Testing
@testable import BestCardEngine

/// Stricter than the golden file: compares the full output of the TypeScript
/// engine (ts_parity.json, regenerated by ios/scripts/ts-parity.sh), including
/// reason text, warning messages and order, the matched merchant and the whole
/// ranking.
struct ParityFile: Decodable, Sendable {
    struct Scored: Decodable, Equatable, Sendable {
        var cardId: String
        var rate: Double
        var centsPerDollar: Double
        var basis: Basis
    }
    struct Case: Decodable, Sendable {
        var id: String
        var cardId: String?
        var rate: Double?
        var centsPerDollar: Double?
        var basis: Basis?
        var category: String
        var foreign: Bool
        var reason: String
        var runnerUp: RunnerUp?
        var warnings: [EngineWarning]
        var merchantMatch: String?
        var ranked: [Scored]
    }
    var cases: [Case]

    static let shared: ParityFile = {
        let url = Bundle.module.url(forResource: "ts_parity", withExtension: "json")!
        return try! JSONDecoder().decode(ParityFile.self, from: Data(contentsOf: url))
    }()
}

extension ParityFile.Case: CustomTestStringConvertible {
    var testDescription: String { id }
}

@Suite("TypeScript parity (ts_parity.json)")
struct ParityTests {
    @Test("covers every golden case")
    func coversGolden() {
        #expect(Set(ParityFile.shared.cases.map(\.id)) == Set(Fixtures.golden.cases.map(\.id)))
    }

    @Test("same output as TypeScript", arguments: ParityFile.shared.cases)
    func sameOutput(_ ts: ParityFile.Case) throws {
        let golden = try #require(Fixtures.golden.cases.first { $0.id == ts.id })
        let r = Fixtures.engine.recommend(golden.input, options: golden.options ?? EngineOptions())
        #expect(r.cardId == ts.cardId)
        #expect(r.rate == ts.rate)
        #expect(r.centsPerDollar == ts.centsPerDollar)
        #expect(r.basis == ts.basis)
        #expect(r.category == ts.category)
        #expect(r.foreign == ts.foreign)
        #expect(r.reason == ts.reason)
        #expect(r.runnerUp == ts.runnerUp)
        #expect(r.warnings == ts.warnings)
        #expect(r.merchant?.match == ts.merchantMatch)
        #expect(r.ranked.map { ParityFile.Scored(cardId: $0.cardId, rate: $0.rate, centsPerDollar: $0.centsPerDollar, basis: $0.basis) } == ts.ranked)
    }
}
